pub const RProxyCase = struct {
    id: []const u8,
    /// The request the client sends to the proxy.
    wire: []const u8,
    /// Header lines the backend adds to its `200 OK` (`Content-Length: 2`, `Content-Type: text/plain`, body `ok`).
    resp_extra: []const u8,
    /// What Go's proxy sent the backend: request line, normalised field lines, body.
    up_line: []const u8,
    up: []const []const u8,
    up_body: []const u8,
    /// What Go's proxy returned to the client: status and normalised field lines.
    status: u16,
    down: []const []const u8,
};

