pub const FormFile = struct { key: []const u8, filename: []const u8, content_type: ?[]const u8, data: []const u8 };

pub const FormCase = struct {
    id: []const u8,
    method: []const u8,
    target: []const u8,
    content_type: []const u8,
    body: []const u8,
    /// > 0: the request body is `body` repeated n times joined by "&".
    n: u32,
    /// Request.ParseForm's error, "" when none.
    parse_err: []const u8,
    /// Request.ParseMultipartForm's error, "" when none or ErrNotMultipart.
    multipart_err: []const u8,
    /// Request.Form / PostForm: keys sorted, a key's values in Go's order;
    /// both empty for a repeated (n > 0) body, whose value counts say it all.
    form: []const [2][]const u8,
    post: []const [2][]const u8,
    form_count: u32,
    post_count: u32,
    /// MultipartForm.File, keys sorted.
    files: []const FormFile,
};

