pub const EscapeCase = struct { input: []const u8, out: []const u8 };

/// Go's url.QueryEscape.
pub const query_escape = [_]EscapeCase{
    .{ .input = "", .out = "" },
    .{ .input = "abc", .out = "abc" },
    .{ .input = "a b", .out = "a+b" },
    .{ .input = "a+b", .out = "a%2Bb" },
    .{ .input = "a&b=c", .out = "a%26b%3Dc" },
    .{ .input = "-_.~", .out = "-_.~" },
    .{ .input = "!*'();:@&=+$,/?#[]", .out = "%21%2A%27%28%29%3B%3A%40%26%3D%2B%24%2C%2F%3F%23%5B%5D" },
    .{ .input = "\xc4\x8d", .out = "%C4%8D" },
    .{ .input = "\x00\x7f\x80\xff", .out = "%00%7F%80%FF" },
    .{ .input = "100%", .out = "100%25" },
    .{ .input = "tab\there", .out = "tab%09here" },
    .{ .input = "A-Z0-9", .out = "A-Z0-9" },
};
